//! Reimplementation of the C++ `inflection` library behavior, inferred
//! black-box from the compiled reference binary.

/// Words that pluralize leaves unchanged (exact, case-sensitive match).
const UNCOUNTABLES: [&str; 10] = [
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

pub struct Inflector;

impl Inflector {
    pub fn initialize() {}

    /// Append "s" unless the word is uncountable.
    pub fn pluralize(word: &str) -> String {
        if UNCOUNTABLES.contains(&word) {
            word.to_string()
        } else {
            let mut s = String::with_capacity(word.len() + 1);
            s.push_str(word);
            s.push('s');
            s
        }
    }

    /// snake_case -> camelCase: first segment kept as-is, every later
    /// segment gets its first character ASCII-uppercased.
    pub fn camelize(word: &str) -> String {
        let mut result = String::with_capacity(word.len());
        for (i, segment) in word.split('_').enumerate() {
            if i == 0 {
                result.push_str(segment);
            } else {
                let mut chars = segment.chars();
                if let Some(first) = chars.next() {
                    result.push(first.to_ascii_uppercase());
                    result.push_str(chars.as_str());
                }
            }
        }
        result
    }

    /// CamelCase -> snake_case: insert '_' before every ASCII-uppercase
    /// character that is not at index 0, then ASCII-lowercase everything.
    pub fn underscore(word: &str) -> String {
        let mut result = String::with_capacity(word.len() + 4);
        for (i, c) in word.chars().enumerate() {
            if c.is_ascii_uppercase() && i > 0 {
                result.push('_');
            }
            result.push(c.to_ascii_lowercase());
        }
        result
    }

    /// Ends with 's' and not uncountable.
    pub fn is_plural(word: &str) -> bool {
        if UNCOUNTABLES.contains(&word) {
            return false;
        }
        word.ends_with('s')
    }

    pub fn is_singular(word: &str) -> bool {
        !Self::is_plural(word)
    }

    /// Everything after the last "::", skipping one extra character
    /// (the reference implementation does `substr(rfind("::") + 3)`).
    /// Aborts when the position is out of range, mirroring the C++
    /// `std::out_of_range` -> terminate -> abort behavior.
    pub fn demodulize(word: &str) -> String {
        let pos = word.rfind("::").map(|p| p + 3).unwrap_or(0);
        match word.get(pos..) {
            Some(s) => s.to_string(),
            None => std::process::abort(),
        }
    }
}

