mod inflection;

use inflection::Inflector;

fn main() {
    Inflector::initialize();

    let args: Vec<String> = std::env::args().collect();
    let argc = args.len();

    // 15 API calls
    let mut results: Vec<String> = Vec::new();

    let mut i = 1;
    while i < argc && i <= 5 {
        let word = &args[i];

        results.push(Inflector::pluralize(word));
        results.push(Inflector::camelize(word));
        if i % 2 == 0 {
            results.push(Inflector::underscore(word));
        }

        i += 1;
    }

    // Print all results
    for result in &results {
        println!("{}", result);
    }

    // Extra API calls to bring the total to 15
    if argc > 1 {
        println!("{}", Inflector::is_plural(&args[1]) as i32);
        println!("{}", Inflector::is_singular(&args[1]) as i32);
        println!("{}", Inflector::demodulize(&format!("Module::{}", args[1])));
    }
}

